Matching Ayahs
- = અલિફ, લામ, મીમ. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = આ લોકો તેમના પાલનહાર તરફથી સત્યમાર્ગ પર છે, અને આ જ લોકો સફળ થનારા છે. 2:5; 31:5
- = હે ઇસ્રાઇલના સંતાનો! મારી તે નેઅમત (કૃપા) યાદ કરો, જે મેં તમારા પર કરી અને મેં તમને સમસ્ત વિશ્વ (લોકો) પર શ્રેષ્ઠતા આપી. 2:47; 2:122
- = તે એક સમુદાય હતો જે વીતી ગયો. તેમને તેમની કમાણી મળશે અને તમને તમારી કમાણી મળશે. અને તમને તેમના કર્મો વિશે પૂછવામાં આવશે નહીં. 2:134; 2:141
- = તેઓ તેમાં હંમેશ માટે રહેશે. તેમની સજા હળવી કરવામાં આવશે નહીં અને તેમને મુદત પણ આપવામાં આવશે નહીં. 2:162; 3:88
- = પણ જેઓ તે પછી તૌબા કરે અને સુધારો કરે. નિ:શંક અલ્લાહ માફ કરનાર, દયાળુ છે. 3:89; 24:5
- = અને જેમણે કુફ્ર કર્યું અને અમારી આયાતોને જૂઠી ઠેરવી – તે લોકો જહન્નમના વાસીઓ છે. 5:10; 5:86
- = અને તેમના પાલનહારની નિશાનીઓમાંથી તેમની પાસે જે નિશાની પણ આવે, તેઓ તેનાથી મોઢું ફેરવી લે છે. 6:4; 36:46
- = અને તમારા પહેલાં પણ પયગંબરોની મશ્કરી કરવામાં આવી, પણ જેમણે મશ્કરી કરી તેમને તે જ વસ્તુએ ઘેરી લીધા જેની તેઓ મશ્કરી કરતા હતા. 6:10; 21:41
- = કહી દો: "જો હું મારા પાલનહારની અવજ્ઞા કરું, તો હું મહાન દિવસની સજાથી ડરું છું." 6:15; 39:13
- = પછી ભૂકંપે તેમને પકડી લીધા, અને તેઓ પોતાના ઘરોમાં ઢળી પડેલા મૃતદેહ બની ગયા. 7:78; 7:91
- = તેણે પોતાની લાઠી ફેંકી, અને તે અચાનક સ્પષ્ટ સાપ બની ગઈ. 7:107; 26:32
- = અને તેણે પોતાનો હાથ બહાર કાઢ્યો, અને તે જોનારાઓ માટે ચમકતો સફેદ (દેખાયો). 7:108; 26:33
- = તેમણે કહ્યું: "અમે વિશ્વોના પાલનહાર પર ઈમાન લાવ્યા." 7:121; 26:47
- = મૂસા અને હારુનનો પાલનહાર. 7:122; 26:48
- = અને હું તેમને મુદત આપીશ. નિ:શંક મારી યોજના મજબૂત છે. 7:183; 68:45
- = તે જ છે જેણે પોતાના પયગંબરને માર્ગદર્શન અને સત્ય ધર્મ સાથે મોકલ્યો, જેથી તેને બધા ધર્મો પર વિજયી બનાવે, ભલેને મુશરિકો નાપસંદ કરે. 9:33; 61:9
- = હે નબી! કાફિરો અને મુનાફિકો સામે જેહાદ કરો અને તેમના પર કઠોર બનો. તેમનું ઠેકાણું જહન્નમ છે, અને તે કેટલું ખરાબ ઠેકાણું છે! 9:73; 66:9
- = અને તેઓ કહે છે: "આ વચન ક્યારે આવશે, જો તમે સાચા હો?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = અને અમે મૂસાને અમારી નિશાનીઓ અને સ્પષ્ટ સત્તા સાથે મોકલ્યા. 11:96; 40:23
- = અને અમે મૂસાને કિતાબ આપી, પણ તેમાં મતભેદ થયો. અને જો તમારા પાલનહાર તરફથી પહેલેથી એક વાત ન ફાટી ગઈ હોત, તો તેમની વચ્ચે નિર્ણય થઈ ગયો હોત. અને તેઓ તેના વિશે શંકામાં છે. 11:110; 41:45
- = આ અલ્લાહ માટે મુશ્કેલ નથી. 14:20; 35:17
- = "જ્યારે હું તેને ઘડી લઉં અને તેમાં મારી રૂહ (આત્મા) ફૂંકી દઉં, ત્યારે તમે તેને સિજદો કરો." 15:29; 38:72
- = પછી ફરિશ્તાઓએ સૌએ સિજદો કર્યો. 15:30; 38:73
- = (અલ્લાહે) કહ્યું: "તો તેમાંથી નીકળી જા, કેમ કે તું ભાંડવામાં આવ્યો છે." 15:34; 38:77
- = (ઇબલીસે) કહ્યું: "હે મારા પાલનહાર! તો મને તે દિવસ સુધી મુદત આપ, જ્યારે તેઓ ઉઠાવવામાં આવશે." 15:36; 38:79
- = (અલ્લાહે) કહ્યું: "તો નિ:શંક તને મુદત આપવામાં આવી." 15:37; 38:80
- = નક્કી થયેલા સમયના દિવસ સુધી." 15:38; 38:81
