- = તેમણે કહ્યું: "તો તમારું શું કામ છે, હે પયગંબરો?" 15:57; 51:31
- = તેમણે કહ્યું: "અમને ગુનેગાર લોકો તરફ મોકલવામાં આવ્યા છે." 15:58; 51:32
