- આ એટલા માટે કે અલ્લાહ સત્ય છે, અને તેઓ તેના સિવાય જેને બોલાવે છે તે અસત્ય છે. (ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ) 22:62; 31:30
- અને જે કોઈ અલ્લાહ અને તેના પયગંબરની આજ્ઞા પાળે છે, અલ્લાહ તેને તે બગીચાઓમાં દાખલ કરશે જેની નીચે નહેરો વહે છે. (وَمَن يُطِعِ اللَّهَ وَرَسُولَهُ يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 4:13; 48:17
- તેણે તમને ફક્ત મૃત પ્રાણી, લોહી, ડુક્કરનું માંસ અને તે જે અલ્લાહ સિવાય બીજા માટે કાપવામાં આવે તે હરામ કર્યું છે. (إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 16:115
- કે તમે અલ્લાહ સિવાય કોઈની બંદગી ન કરો; હું તમારા માટે મહાન દિવસના અઝાબથી ડરું છું. (أَن لَّا تَعْبُدُوا إِلَّا اللَّهَ إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ) 11:26; 46:21
- આ ગુપ્ત સમાચારોમાંથી છે જે અમે તમારી તરફ વહી મોકલીએ છીએ; જ્યારે તેઓ નિર્ણય લેતા હતા ત્યારે તમે તેમની પાસે ન હતા. (ذَلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ) 3:44; 12:102
- શું તમને આશ્ચર્ય થાય છે કે તમારા પાલનહાર તરફથી તમારા પોતાના માણસ દ્વારા તમને યાદગીરી આવી, જેથી તે તમને ચેતવે? (أَوَعَجِبْتُمْ أَن جَاءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَى رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ) 7:63; 7:69
- કહે દો: "મને એ વસ્તુઓની બંદગી કરવાથી મના કરવામાં આવી છે જેને તમે અલ્લાહ સિવાય બોલાવો છો." (قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ) 6:56; 40:66
- તેમની પત્નીઓ સિવાય અથવા જેના પર તેમના જમણા હાથનો કબજો છે, કારણ કે તે દોષપાત્ર નથી. (إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ) 23:6; 70:30
- કારણ કે અલ્લાહ રાતને દિવસમાં દાખલ કરે છે અને દિવસને રાતમાં દાખલ કરે છે. (بِأَنَّ اللَّهَ يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ) 22:61; 31:29
- અગ્નિ, અને તેણે તેના કુટુંબને કહ્યું: "ઉભા રહો, મેં આગ જોઈ, કદાચ હું તેમાંથી તમારા માટે કંઈક લાવી શકું." (نَارًا فَقَالَ لِأَهْلِهِ امْكُثُوا إِنِّي آنَسْتُ نَارًا لَّعَلِّي آتِيكُم مِّنْهَا) 20:10; 28:29
- તેણે કહ્યું: "હું તેના કરતાં શ્રેષ્ઠ છું; તમે મને આગથી બનાવ્યો અને તેને માટીથી બનાવ્યો." (قَالَ أَنَا خَيْرٌ مِّنْهُ خَلَقْتَنِي مِن نَّارٍ وَخَلَقْتَهُ مِن طِينٍ) 7:12; 38:76
- અને જ્યારે તેમને કહેવામાં આવે છે: "અલ્લાહે જે ઉતાર્યું છે તે તરફ અને પયગંબર તરફ આવો." (وَإِذَا قِيلَ لَهُمْ تَعَالَوْا إِلَى مَا أَنزَلَ اللَّهُ وَإِلَى الرَّسُولِ) 4:61; 5:104
- અને તમે તેમના માટે દુઃખી ન થાઓ, અને તેઓ જે કાવતરાં કરે છે તેના કારણે સંકુચિત ન થાઓ. (وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِي ضَيْقٍ مِّمَّا يَمْكُرُونَ) 16:127; 27:70
- અને જો અલ્લાહ તમને કોઈ તકલીફ પહોંચાડે, તો તેના સિવાય કોઈ તેને દૂર કરી શકે નહીં, અને જો. (وَإِن يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ وَإِن) 6:17; 10:107
- તેમના પહેલાંની પેઢીઓ જે તેમના ઘરોમાં ફરતી હતી; નિશ્ચિતપણે તેમાં નિશાનીઓ છે. (قَبْلَهُم مِّنَ الْقُرُونِ يَمْشُونَ فِي مَسَاكِنِهِمْ إِنَّ فِي ذَلِكَ لَآيَاتٍ) 20:128; 32:26
- અને અમે તેમના દિલો પર પડદા નાખ્યા જેથી તેઓ તેને સમજી ન શકે, અને તેમના કાનમાં ભારેપણું, અને જો. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا وَإِن) 6:25; 18:57
- તેમના પયગંબરો સ્પષ્ટ પુરાવાઓ સાથે તેમની પાસે આવ્યા, પરંતુ અલ્લાહ તેમના પર અત્યાચાર કરનાર ન હતો, પરંતુ તેઓ પોતાને પર અત્યાચાર કરતા હતા. (رُسُلُهُم بِالْبَيِّنَاتِ فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 30:9
- અને પૃથ્વી પર, અને અલ્લાહ સિવાય તમારો કોઈ વાલી અને ન સહાયક છે. (وَالْأَرْضِ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 42:31
- પછી તમને ગુપ્ત અને પ્રગટના જાણનારની પાસે પરત લાવવામાં આવશે, અને તે તમને જણાવશે જે તમે કરતા હતા. (ثُمَّ تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 62:8
- રાત, જેથી તમે તેમાં આરામ કરો, અને દિવસ, જેથી તમે જુઓ; નિશ્ચિતપણે તેમાં વિચાર કરનારા લોકો માટે નિશાનીઓ છે. (اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ فِي ذَلِكَ لَآيَاتٍ لِّقَوْمٍ) 10:67; 27:86
- અને તમારા પાલનહાર તરફથી જે તમારી તરફ ઉતારવામાં આવ્યું છે, તે તેમાંથી ઘણાના વિદ્રોહ અને કુફ્રમાં વધારો કરશે. (وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَانًا وَكُفْرًا) 5:64; 5:68
- તેણે કહ્યું: "હે મારી કોમના લોકો! મને કહો, જો હું મારા પાલનહાર તરફથી સ્પષ્ટ પુરાવા પર હોઉં અને તેણે મને આપ્યું હોય." (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي وَآتَانِي) 11:28; 11:63
- અને તેઓ કહે છે: "તેના પર તેના પાલનહાર તરફથી કોઈ નિશાની કેમ ન ઉતારવામાં આવી?" કહે દો: "નિશ્ચિતપણે." (وَيَقُولُونَ لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 29:50
- તે દિવસ આવતા પહેલા જેનું અલ્લાહ તરફથી કોઈ પાછું ફેરણું નથી. (مِن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا مَرَدَّ لَهُ مِنَ اللَّهِ) 30:43; 42:47
- તે અલ્લાહની કૃપા છે, જે તે ઇચ્છે છે તેને આપે છે, અને અલ્લાહ મહાન કૃપાનો માલિક છે. (ذَلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 62:4
- અને નિશ્ચિતપણે, ઢોરમાં તમારા માટે શિક્ષણ છે; અમે તમને તેમના પેટમાંની વસ્તુઓમાંથી પીવડાવીએ છીએ. (وَإِنَّ لَكُمْ فِي الْأَنْعَامِ لَعِبْرَةً نُّسْقِيكُم مِّمَّا فِي بُطُونِهِ) 16:66; 23:21
- કે તે તેમના પાલનહાર તરફથી સત્ય છે, અને અલ્લાહ જે તેઓ કરે છે તેનાથી ગાફલ નથી. (أَنَّهُ الْحَقُّ مِن رَّبِّهِمْ وَمَا اللَّهُ بِغَافِلٍ عَمَّا يَعْمَلُونَ) 2:144; 2:149
- તેમની આગળ અને પાછળ, કે તમે અલ્લાહ સિવાય કોઈની બંદગી ન કરો. (مِن بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلَّا تَعْبُدُوا إِلَّا اللَّهَ) 41:14; 46:21
- નિશ્ચિતપણે, તમે સ્ત્રીઓને છોડીને પુરુષો પાસે વાસનાથી આવો છો; બલકે, તમે હદ વટાવનારા લોકો છો. (إِنَّكُمْ لَتَأْتُونَ الرِّجَالَ شَهْوَةً مِّن دُونِ النِّسَاءِ بَلْ أَنتُمْ قَوْمٌ) 7:81; 27:55
- તેઓ તેમાં હંમેશા રહેશે, જ્યાં સુધી આકાશ અને પૃથ્વી છે, સિવાય કે તમારા પાલનહાર ઇચ્છે. (خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالْأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ) 11:107; 11:108
- જે આકાશોમાં છે અને જે પૃથ્વીમાં છે, સિવાય કે અલ્લાહ ઇચ્છે. (مَن فِي السَّمَاوَاتِ وَمَن فِي الْأَرْضِ إِلَّا مَن شَاءَ اللَّهُ) 27:87; 39:68
- ત્યાં તેઓને સોનાના કડા અને મોતીથી શણગારવામાં આવશે, અને તેમના વસ્ત્રો ત્યાં રેશમના હશે. (يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ) 22:23; 35:33
- અને તેણે આકાશમાંથી પાણી ઉતાર્યું, અને તેના દ્વારા તમારા માટે ફળો ઉત્પન્ન કર્યા. (وَأنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِ مِنَ الثَّمَرَاتِ રِزْقًا لَّكُمْ) 2:22; 14:32
- અને જ્યારે અમે તમારો કરાર લીધો અને તમારા ઉપર તુર પર્વત ઉચ્ચો કર્યો: "અમે જે આપ્યું છે તે મજબૂતીથી પકડો." (وَإِذْ أَخَذْنَا مِيثَاقَكُمْ وَرَفَعْنَا فَوْقَكُمُ الطُّورَ خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ) 2:63; 2:93
- અને તેણે તેમનાથી મોં ફેરવ્યું અને કહ્યું: "હે મારી કોમના લોકો! મેં તમને મારા પાલનહારનો સંદેશ પહોંચાડી દીધો અને તમને નસીહત કરી." (فَتَوَلَّى عَنْهُمْ وَقَالَ يَاقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَالَةَ رَبِّي وَنَصَحْتُ لَكُمْ) 7:79; 7:93
