- અને જે કૃતજ્ઞ થાય, તે પોતાના માટે જ કૃતજ્ઞ થાય; અને જે અકૃતજ્ઞ થાય. (وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ) 27:40; 31:12
- જેઓ નમાઝ પાઠવે છે, ઝકાત આપે છે અને આખિરત પર દૃઢ વિશ્વાસ રાખે છે. (الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ) 27:3; 31:4
- ઇબ્રાહિમ, ઇસ્માઇલ, ઇસ્હાક, યાકૂબ અને કુળોને, અને મૂસા અને ઈસાને જે આપવામાં આવ્યું. (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
- સમૂહો સમૂહોમાં, જ્યાં સુધી તેઓ ત્યાં ન પહોંચે, અને તેના દરવાજા ખોલવામાં આવે, અને તેના રક્ષકો તેમને કહે. (زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا) 39:71; 39:73
- અલ્લાહ તમને તમારા સોગંદોની બેકાર વાતો પર પકડશે નહીં, પરંતુ તે તમને તેના પર પકડશે. (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- દયા, તેઓ તેનાથી ખુશ થાય છે, અને જો તેમને તેમના હાથે કરેલા કાર્યોના કારણે કોઈ તકલીફ પહોંચે. (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- બગીચાઓ જેની નીચે નહેરો વહે છે, જેમાં તેઓ હંમેશા રહેશે, અને કામ કરનારાઓનો બદલો કેટલો સુંદર છે! (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- અલ્લાહ જાણે છે જે આકાશોમાં છે અને જે પૃથ્વીમાં છે, અને અલ્લાહ. (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- અલ્લાહની આજ્ઞા પાળો અને પયગંબરની આજ્ઞા પાળો; પરંતુ જો તમે મોં ફેરવો, તો તેના પર (ફરજ) છે. (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- તેમને તેમના પાલનહાર પાસે તેમનો બદલો છે, અને તેમના પર કોઈ ડર નથી, અને તેઓ. (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- અને તેઓએ કહ્યું: "જ્યારે અમે હાડકાં અને ધૂળ બની જઈશું, તો શું અમે નવી સૃષ્ટિ તરીકે ઉઠાવવામાં આવશે?" (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- અને તેઓ પોતાના માટે અલ્લાહ સિવાય કોઈ વાલી કે સહાયક નહીં શોધે. (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
- "તમે કેટલો સમય રોકાયા?" તેણે કહ્યું: "હું એક દિવસ કે દિવસનો થોડો ભાગ રોકાયો." તેણે કહ્યું. (كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ) 2:259; 18:19
- કિયામતના દિવસ સુધી, અલ્લાહ સિવાય કોણ ઈશ્વર છે જે તમને લાવી શકે? (سَرْمَدًا إِلَى يَوْمِ الْقِيَامَةِ مَنْ إِلَهٌ غَيْرُ اللَّهِ يَأْتِيكُم) 28:71; 28:72
- જે સત્કર્મ કરે, પુરુષ હોય કે સ્ત્રી, અને તે ઈમાનવાળો હોય. (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- જેઓ અલ્લાહના માર્ગથી રોકે છે અને તેને ટेढો બનાવવા માંગે છે, અને તેઓ આખિરતમાં. (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- જ્યાં ઇચ્છો ત્યાં ખાઓ, પરંતુ આ વૃક્ષની નજીક ન જાવ, નહીંતર તમે અત્યાચારીઓ બની જશો. (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- કહે દો: "હે મારી કોમના લોકો! તમે તમારી જગ્યાએ કામ કરો, હું પણ કામ કરું છું, અને ટૂંક સમયમાં તમે જાણી લેશો." (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- નિશ્ચિતપણે, નુકસાન ઉઠાવનારાઓ તે છે જેમણે કિયામતના દિવસે પોતાને અને પોતાના પરિવારને નુકસાન પહોંચાડ્યું, સાવધાન. (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- જે સત્યમાર્ગ અપનાવે, તે પોતાના માટે અપનાવે; અને જે ભટકે, તે પોતાના માટે ભટકે; અને. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
- અને જે લોકો કાફિર છે તેઓ કહે છે: "તેના પર તેના પાલનહાર તરફથી કોઈ નિશાની કેમ ન ઉતારવામાં આવી?" (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- જેણે તમારા માટે રાત બનાવી જેથી તમે તેમાં આરામ કરો, અને દિવસ, જેથી તમે જુઓ, નિશ્ચિતપણે. (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
- તે દિવસ આવતા પહેલા જેમાં કોઈ વેપાર કે મિત્રતા નથી. (مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا) 2:254; 14:31
- જેથી તેઓ વિચારે કે તેમના સાથીને કોઈ પાગલપણું નથી; તે તો ફક્ત ચેતવનારો છે. (يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ) 7:184; 34:46
- તેઓ તેમાં હંમેશા રહેશે, તેમના પર અઝાબ હળવો નહીં કરવામાં આવે, અને તેમને મુદત નહીં આપવામાં આવે. (خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ) 2:162; 3:88
- તમારી નજરોને તે વસ્તુઓ તરફ ન ફેલાવો જે અમે તેમાંથી કેટલાકને આનંદ માટે આપી છે. (لَا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ) 15:88; 20:131
- અને લોકોને તેમની વસ્તુઓમાં ઓછું ન આપો, અને પૃથ્વી પર ઉપદ્રવ ન ફેલાવો. (وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ) 11:85; 26:183
- અને તેના પર સલામ છે જે દિવસે તે જન્મ્યો, અને જે દિવસે તે મરશે, અને જે દિવસે તે જીવિત ઉઠાવવામાં આવશે. (وَسَلَامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا) 19:15; 19:33
- હે મારી કોમના લોકો! તમે તમારી જગ્યાએ કામ કરો, હું પણ કામ કરું છું, અને ટૂંક સમયમાં તમે જાણી લેશો કે કોણ. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن) 6:135; 11:93
- અને કોઈ પયગંબર માટે અલ્લાહની પરવાનગી વિના કોઈ નિશાની લાવવી શક્ય નથી. (وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ) 13:38; 40:78
- પછી દરેક જીવને તેણે કરેલા કાર્યોનો સંપૂર્ણ બદલો આપવામાં આવશે, અને તેમના પર અત્યાચાર નહીં થાય. (ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:161
- પુરુષ હોય કે સ્ત્રી, અને તે ઈમાનવાળો હોય, તો તે લોકો જન્નતમાં દાખલ થશે. (مِن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ فَأُولَئِكَ يَدْخُلُونَ الْجَنَّةَ) 4:124; 40:40
- તેણે કોઈ સંતાન ધારણ કર્યું નથી અને રાજ્યમાં તેનો કોઈ ભાગીદાર નથી. (لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ) 17:111; 25:2
- અને અલ્લાહ જેને સત્યમાર્ગ બતાવે, તે જ સત્યમાર્ગી છે; અને જેને તે ભટકાવે, તમે ક્યારેય નહીં શોધી શકો. (وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ) 17:97; 18:17
- જો, તેઓ તમારા માટે કેવા દાખલાઓ બનાવે છે, પછી તેઓ ભટકી ગયા, અને તેઓ માર્ગ શોધી શક્યા નહીં. (انظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ فَضَلُّوا فَلَا يَسْتَطِيعُونَ سَبِيلًا) 17:48; 25:9
- કહે દો: "હું ડરું છું, જો હું મારા પાલનહારની અવજ્ઞા કરું, તો મહાન દિવસના અઝાબથી." (قُلْ إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 39:13
- તેમની શરમની જગ્યાઓ ખુલ્લી થઈ ગઈ, અને તેઓ જન્નતના પાંદડાઓથી પોતાને ઢાંકવા લાગ્યા. (بَدَتْ لَهُمَا سَوْآتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ) 7:22; 20:121
- અને અલ્લાહ સિવાય જેને તમે બોલાવી શકો તેને બોલાવો, જો તમે સાચા હોવ. (وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَادِقِينَ) 10:38; 11:13
- પૃથ્વી પરની બધી વસ્તુઓ અને તેટલી જ વધુ, જેથી તેઓ તેના દ્વારા પોતાને બચાવી શકે. (مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا بِهِ مِنْ) 5:36; 39:47
