- તેના પાલનહાર તરફથી તેના પર કોઈ નિશાની કેમ ન ઉતારવામાં આવી? કહો: નિશ્ચિતપણે. (لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 13:27; 29:50
- જે લોકો ઈમાન લાવ્યા અને સત્કર્મો કર્યા, તેમના માટે અખૂટ બદલો છે. (الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 41:8; 84:25; 95:6
- તું જીવંતને મૃતમાંથી બહાર કાઢે છે અને મૃતને જીવંતમાંથી બહાર કાઢે છે. (وَتُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَتُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ) 3:27; 10:31; 30:19
- જે અલ્લાહે ઉતારેલા કાયદા પ્રમાણે ફેસલો ન કરે, તે લોકો. (وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللَّهُ فَأُولَئِكَ هُمُ) 5:44; 5:45; 5:47
- તેણે આકાશો અને ધરતી અને તેમની વચ્ચેની દરેક વસ્તુ છ દિવસમાં બનાવી. (خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ) 25:59; 32:4; 50:38
- નિશ્ચિતપણે અલ્લાહ લોકો પર મહાન કૃપાશીલ છે, પરંતુ મોટાભાગના. (إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ) 2:243; 10:60; 40:61
- અલ્લાહ તેમના પર જુલમ કરનાર ન હતો, પરંતુ તેઓ પોતાના પર જ જુલમ કરતા હતા. (فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 29:40; 30:9
- તે તમારા પાપોને માફ કરશે અને તમને એવા બગીચાઓમાં દાખલ કરશે, જેની નીચે નહેરો વહે છે. (عَنكُمْ سَيِّئَاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 5:12; 64:9; 66:8
- તેણે તમારા પર મૃત પ્રાણી, લોહી, ડુક્કરનું માંસ અને જે અલ્લાહ સિવાય બીજાના નામે વધેરવામાં આવે, તે હરામ કર્યું છે. (حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 5:3; 16:115
- હું ડરું છું, જો હું મારા પાલનહારની અવજ્ઞા કરીશ, તો મહાન દિવસની યાતનાનો. (إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 10:15; 39:13
- પરંતુ તેમની પાસે જ્ઞાન આવ્યા પછી, તેમની વચ્ચેની ઈર્ષાના કારણે. (إِلَّا مِن بَعْدِ مَا جَاءَهُمُ الْعِلْمُ بَغْيًا بَيْنَهُمْ) 3:19; 42:14; 45:17
- તેઓ નમાઝ પઢે છે અને અમે તેમને જે રોજી આપી છે, તેમાંથી છુપી રીતે અને જાહેર રીતે ખર્ચ કરે છે. (وَأَقَامُوا الصَّلَاةَ وَأَنفَقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَةً) 13:22; 14:31; 35:29
- શું અમે અલ્લાહને છોડીને એવાની બંદગી કરીએ, જે અમને ન ફાયદો પહોંચાડી શકે અને ન નુકસાન? (مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا) 6:71; 10:106; 25:55
- તેઓ તેના પર ઈમાન લાવે છે જે તમારી તરફ ઉતારવામાં આવ્યું છે અને તમારા પહેલાં ઉતારવામાં આવ્યું છે. (يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ) 2:4; 4:60; 4:162
- શું તમે નથી જોતા કે અલ્લાહ આકાશમાંથી પાણી વરસાવે છે? (أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً) 22:63; 35:27; 39:21
- જ્યારે તે કોઈ કામનો નિર્ણય કરે છે, ત્યારે તેને કહે છે: થઈ જા, અને તે થઈ જાય છે. (قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 3:47; 19:35; 40:68
- અને મદયન તરફ તેમના ભાઈ શુએબને (મોકલ્યા). તેણે કહ્યું: હે મારી કોમના લોકો! અલ્લાહની બંદગી કરો. (وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ) 7:85; 11:84; 29:36
- આ ગુપ્ત સમાચારોમાંથી છે, જે અમે તમારી તરફ વહી (પ્રકાશના) મારફતે મોકલીએ છીએ; તમે આ જાણતા ન હતા. (ذَلِكَ مِنْ أَنْبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ) 3:44; 11:49; 12:102
- જ્યારે તેમની નિર્ધારિત અવધિ આવે છે, ત્યારે તેઓ એક ક્ષણ પણ મોડું કરી શકતા નથી, કે નહીં વહેલું. (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- શેતાનના પગલે ન ચાલો, નિશ્ચિતપણે તે તમારો ખુલ્લો દુશ્મન છે. (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- કેટલાક લોકો અલ્લાહ વિશે વિના જ્ઞાને દલીલ કરે છે. (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- અલ્લાહ તેને જેને ચાહે આપે છે, અને અલ્લાહ મહાન કૃપાશીલ છે. (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- દરેક વ્યક્તિને તેણે કરેલા કર્મનો પૂરેપૂરો બદલો આપવામાં આવશે, અને તેમના પર જુલમ નહીં થાય. (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- અલ્લાહે જે પ્રાણને હરામ કર્યો છે, તેને હક વગર ન મારો. (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- જ્યારે તે કોઈ કામનો નિર્ણય કરે છે, ત્યારે તેને કહે છે: થઈ જા. (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- તમે જહન્નમના દરવાજામાં પ્રવેશો, ત્યાં હંમેશા રહેશો; અને અહંકારીઓનું રહેઠાણ કેટલું ખરાબ છે! (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- શું તમે તે લોકોને જોયા નથી, જેમને કિતાબનો કોઈ હિસ્સો આપવામાં આવ્યો હતો? (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- તેમના માટે એવા બગીચાઓ છે, જેની નીચે નહેરો વહે છે, ત્યાં તેઓ હંમેશા રહેશે. (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- હે મારી કોમના લોકો! તમે તમારી જગ્યાએ કામ કરો, હું પણ કામ કરું છું, પછી તમને ખબર પડી જશે. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- જે અલ્લાહ અને તેના પયગંબરનો વિરોધ કરે છે, તેના માટે જહન્નમની આગ છે, જ્યાં તે હંમેશા રહેશે. (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- અમે તેમના દિલો પર આવરણ ચઢાવી દીધાં છે, જેથી તેઓ તેને ન સમજે, અને તેમના કાનમાં ભારેપણું. (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- કોઈ પણ વસાહતમાં અમે જ્યારે સચેત કરનાર મોકલ્યો, તો તેના ધનાઢ્ય લોકોએ કહ્યું: અમે. (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- તેઓએ કહ્યું: તમારા પાલનહારને અમારા માટે દુઆ કરો કે તે અમને સ્પષ્ટ કરે કે તે શું છે. (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- તેઓ કહેશે: અલ્લાહ. કહો: બધી પ્રશંસા અલ્લાહ માટે છે! પરંતુ તેમાંના મોટાભાગના. (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- તેના લોકોનો જવાબ ફક્ત એ હતો કે તેઓએ કહ્યું: તેમને બહાર કાઢો. (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- જેની નીચે નહેરો વહે છે, ત્યાં તેઓ હંમેશા રહેશે; આ જ મહાન સફળતા છે. (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- આ લોકો તેમના પાલનહાર તરફથી માર્ગદર્શન પર છે, અને આ લોકો જ સફળ છે. (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- જેને અપમાનજનક યાતના આવી પહોંચે અને તેના પર સ્થાયી યાતના ઉતરી આવે. (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- ધરતી પર ફરો અને જુઓ કે જેઓએ (સત્યને) જૂઠું ઠરાવ્યું, તેમનો અંત કેવો થયો. (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- તેઓ તેને ક્યારેય ઇચ્છશે નહીં, તેમના હાથે આગળ મોકલેલા કર્મોના કારણે, અને અલ્લાહ જાલિમોને સારી રીતે જાણે છે. (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- તે સારી રીતે જાણે છે કે કોણ તેના માર્ગથી ભટક્યું છે, અને તે સારી રીતે જાણે છે. (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- નિશ્ચિતપણે અલ્લાહ મારો પાલનહાર છે અને તમારો પાલનહાર છે, તો તેની જ બંદગી કરો; આ જ સીધો માર્ગ છે. (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- તે લોકો પર મહાન કૃપાશીલ છે, પરંતુ તેમાંના મોટાભાગના આભારી નથી. (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- આકાશો અને ધરતી અને તેમની વચ્ચેની દરેક વસ્તુને અમે ફક્ત સત્ય સાથે અને નિર્ધારિત સમય માટે જ બનાવી છે. (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- તેમને તેમના વ્યર્થ વાદવિવાદમાં અને રમતમાં પડેલા છોડી દો, જ્યાં સુધી તેઓ તેમના તે દિવસને ન મળે, જેનું વચન તેમને આપવામાં આવ્યું છે. (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- જ્યારે તેઓ ઈમાનવાળાઓને મળે છે, ત્યારે કહે છે: અમે ઈમાન લાવ્યા, અને જ્યારે એકબીજાથી અલગ થાય છે. (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- તેઓ તૌરાત અને ઇંજીલ અને તેમના પાલનહાર તરફથી તેમની તરફ જે ઉતારવામાં આવ્યું છે, તેને કાયમ રાખે છે. (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- તે જાણે છે જે તેમની સામે છે અને જે તેમની પાછળ છે, અને તેઓ તેને પોતાના જ્ઞાનથી ઘેરી શકતા નથી. (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- અને તે જ છે જેણે આકાશો અને ધરતી છ દિવસમાં બનાવી. (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- નિશ્ચિતપણે તેમાં તમારા માટે નિશાની છે, જો તમે ઈમાન લાવનારા હોવ. (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- જ્યારે માર્ગદર્શન આવી ગયું, તો લોકોને ઈમાન લાવવાથી શું રોક્યા? (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- અને તેઓએ અલ્લાહના સમાંતર ભાગીદારો બનાવ્યા, જેથી તેમના માર્ગથી ભટકાવે. કહો: મજા કરો. (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- અને તેઓને આશ્ચર્ય થયું કે તેમની વચ્ચેથી જ એક સચેત કરનાર તેમની પાસે આવ્યો, અને કાફિરોએ કહ્યું: આ. (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- નિશ્ચિતપણે તમારો પાલનહાર સારી રીતે જાણે છે કે કોણ તેના માર્ગથી ભટક્યું છે. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- તે વ્યક્તિના જેવું, જે પોતાનું ધન લોકોને બતાવવા માટે ખર્ચે છે અને અલ્લાહ પર ઈમાન નથી રાખતો. (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- અમે તમને જે રોજી આપી છે, તેમાંથી તેના આવવા પહેલાં ખર્ચ કરો. (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- તેણે આકાશોમાં અને ધરતીમાં જે કંઈ છે, તે બધું તમારા માટે વશ કરી દીધું છે. (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- અને અમે તો તે વિશે શંકામાં છીએ, જે તરફ તમે અમને બોલાવો છો. (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- નિશ્ચિતપણે તમારો પાલનહાર જેને ઇચ્છે રોજી પહોળી કરે છે અને સંકોચે છે. નિશ્ચિતપણે તે. (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- આકાશો અને ધરતી અને તેમની વચ્ચેની દરેક વસ્તુનો પાલનહાર, જો તમે દૃઢ વિશ્વાસ ધરાવતા હોવ. (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- અમે અલ્લાહ પર ઈમાન લાવ્યા અને અમારી તરફ જે ઉતારવામાં આવ્યું છે અને (પહેલાના પયગંબરો) તરફ જે ઉતારવામાં આવ્યું છે. (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- અને જે લોકોએ જુલમ કર્યો, તેમને ભયંકર ધ્વનિએ પકડી લીધા, પછી તેઓ પોતાના ઘરોમાં બેઠેબેઠે મરણ પામ્યા. (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- સ્ત્રીઓ પોતાના વિશે જે કરે છે, તેમાં તમારા પર કોઈ ગુનાહ નથી. (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- તમારો પાલનહાર સારી રીતે જાણે છે કે કોણ તેના માર્ગથી ભટક્યું છે, અને તે. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- તેના આદેશથી રૂહ (વહી) તેના બંદાઓમાંથી જેને ઇચ્છે તેના પર ઉતારે છે. (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- અને અમે મરયમના દીકરા ઈસાને સ્પષ્ટ નિશાનીઓ આપી અને તેને પવિત્ર આત્મા વડે મજબૂત કર્યા. (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- જેથી કિયામતના દિવસે તેમની વચ્ચે, જે વાતમાં તેઓ મતભેદ કરતા હતા, તેનો ફેંસલો કરે. (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- અમે તેના ઉપરના ભાગને નીચેનો બનાવી દીધો અને તેના પર પકવેલી માટીના પથ્થરોનો વરસાદ વરસાવ્યો. (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- તેમના માટે સરખું છે, ભલે તેમને સચેત કરો કે ન કરો, તેઓ ઈમાન નહીં લાવે. (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- લોકોને છોડીને, જો તમે સાચા હોવ, તો મૃત્યુની ઇચ્છા કરો. (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- અલ્લાહની (બંદગી કરો), તેના સિવાય તમારો કોઈ ઈલાહ નથી. શું તમે ડરતા નથી? (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- પછી ભલે અમે તમને તેનો કોઈ ભાગ બતાવીએ, જેની ધમકી અમે તેમને આપીએ છીએ, અથવા તમને મૃત્યુ આપીએ, તો તેમનું પાછું ફરવું તો અમારી તરફ જ છે. (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- તેઓએ કહ્યું: જ્યારે અમે મરી જઈશું અને માટી અને હાડકાં થઈ જઈશું, તો શું અમને ફરીથી જીવિત કરવામાં આવશે? (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- નિશ્ચિતપણે કૃપા અલ્લાહના હાથમાં છે, તે જેને ઇચ્છે આપે છે, અને અલ્લાહ. (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- અને તમે ગુપ્ત અને ખુલ્લા દરેક વસ્તુને જાણનાર તરફ પાછા ફેરવવામાં આવશો, પછી તે તમને જણાવશે જે કંઈ તમે કરતા હતા. (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- હે ઈમાન લાવનારાઓ! અલ્લાહની તે કૃપાને યાદ કરો, જ્યારે. (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- અને અમે તમારા પહેલાં પણ ફક્ત પુરુષોને જ પયગંબર બનાવીને મોકલ્યા, જેમની તરફ અમે વહી (પ્રકાશના) મોકલતા. (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- તે તેના પાપોને માફ કરશે અને તેને એવા બગીચાઓમાં દાખલ કરશે, જેની નીચે નહેરો વહે છે. (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- જે બીમાર હોય કે સફર પર હોય, તો બીજા દિવસોમાં ગણતરી પૂરી કરે. (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- તેઓ ફક્ત અંદાજ અને અટકળ પાછળ જાય છે. (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- જે અલ્લાહ અને અંતિમ દિવસની આશા રાખે છે, તેના માટે ઉત્તમ આદર્શ છે. (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- અમે આકાશો અને ધરતી અને તેમની વચ્ચેની દરેક વસ્તુને ફક્ત સત્ય સાથે જ બનાવી છે. (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- તમારો હાથ તમારી કોઠીમાં નાખો, તે કોઈ રોગ વિના ઉજ્જવળ થઈને બહાર આવશે. (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- તે પોતાની કૃપાથી જેને ઇચ્છે પસંદ કરે છે, અને અલ્લાહ મહાન કૃપાશીલ છે. (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- શું તમે નથી જાણતા કે અલ્લાહ માટે જ આકાશો અને ધરતીનું રાજ્ય છે? (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- તમે તમારા માટે જે કંઈ ભલાઈ આગળ મોકલશો, તે તમે અલ્લાહ પાસે પામશો. (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- અને તમે જ્યાંથી પણ નીકળો, તમારું મુખ મસ્જિદ-અલ-હરામ તરફ ફેરવો. (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- તમારા પહેલાંના લોકો પણ (આવી રીતે) પસાર થઈ ગયા, અને તમે અલ્લાહના કાયદામાં કોઈ ફેરફાર જોશો નહીં. (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- તે જ છે, જેના માટે આકાશો અને ધરતીમાં જે કંઈ છે, તે બધું છે. (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- કોઈ સ્ત્રી ગર્ભ ધારણ કરતી નથી કે જન્મ આપતી નથી, પરંતુ તેના જ્ઞાનથી. (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- તેણે રાત અને દિવસ, સૂર્ય અને ચંદ્રને વશ કરી દીધા છે; દરેક એક નિર્ધારિત સમય સુધી ચાલે છે. (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- જેની નીચે નહેરો વહે છે, ત્યાં તેઓ હંમેશા રહેશે, અને આ જ બદલો છે. (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- તેણે કહ્યું: ના, તમારા મનોભાવોએ તમારા માટે એક વાતને શણગારી છે; તો ધીરજ સુંદર છે. (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- જે કંઈ આકાશોમાં અને ધરતીમાં છે, અને નિશ્ચિતપણે અલ્લાહ. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- તેમની પાસે જે પયગંબર આવ્યો, તેની સાથે તેઓ મજાક કરતા. (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- તેઓએ કહ્યું: હે મૂસા! કાં તો તમે ફેંકો, અથવા અમે ફેંકીએ? (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- તે જ તમને મૃત્યુ આપે છે, અને તમારામાંથી કેટલાકને સૌથી વૃદ્ધાવસ્થા તરફ પાછા ફેરવે છે, જેથી. (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- તેમના માટે તેમના પાલનહાર પાસે એવા બગીચાઓ છે, જેની નીચે નહેરો વહે છે, ત્યાં તેઓ હંમેશા રહેશે. (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- અને અમે તેમના દિલો પર આવરણ ચઢાવી દીધાં છે, જેથી તેઓ તેને ન સમજે, અને તેમના કાનમાં ભારેપણું. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- અલ્લાહનું વચન સાચું છે, પરંતુ તેમાંના મોટાભાગના જાણતા નથી. (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- આ એટલા માટે કે તેઓએ અલ્લાહ અને તેના પયગંબરનો વિરોધ કર્યો; અને જે અલ્લાહનો વિરોધ કરે છે. (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- અને જે દિવસે તે તેમને બોલાવશે અને કહેશે: મારા ભાગીદારો ક્યાં છે, જેમને તમે ધારણા કરતા હતા? (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- શું તેઓએ જોયું નથી કે અલ્લાહ, જેણે આકાશો અને ધરતી બનાવી છે, તે તેમના જેવા બનાવવા સમર્થ છે? (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- (તે) જેણે તમને માટીમાંથી, પછી વીર્યમાંથી, પછી. (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- તેઓ કહેશે: હે અમારા પાલનહાર! જો તમે અમારી તરફ કોઈ પયગંબર મોકલ્યો હોત, તો અમે તમારી નિશાનીઓનું અનુસરણ કરત. (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- પછી તેમનું પાછું ફરવું તેમના પાલનહાર તરફ છે, પછી તે તેમને જણાવશે જે કંઈ તેઓ કરતા હતા. (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- તેમને તેનું કોઈ જ્ઞાન નથી; તેઓ ફક્ત અનુમાન પાછળ છે. (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- અમે અમારા બાપદાદાઓને એક ધર્મ પર પામ્યા, અને અમે તેમના પગલે ચાલીએ છીએ. (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- જેમને કિતાબ આપવામાં આવી, તેઓએ જ્ઞાન આવ્યા પછી જ (મતભેદ કર્યો). (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- અને જ્યારે ઇબ્રાહીમે કહ્યું: હે મારા પાલનહાર! આ શહેરને સલામત બનાવ. (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- તેણે તમારા માટે કાન, આંખો અને દિલ બનાવ્યા; તમે ઘણું ઓછું આભાર માનો છો. (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- જે લોકો અલ્લાહની નિશાનીઓ વિશે વિના કોઈ સત્તાધિકારે દલીલ કરે છે. (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- તો ઇબ્રાહીમના સાચા ધર્મનું અનુસરણ કરો, જે એકેશ્વરવાદી હતા, અને તેઓ મુશરિકોમાંથી ન હતા. (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- અને જ્યારે અમે તમને ફિરઔનના કુટુંબીઓથી બચાવ્યા, જેઓ તમને સખત યાતના આપતા હતા. (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- આ જ સાચો ધર્મ છે, પરંતુ મોટા ભાગના લોકો જાણતા નથી. (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- શું તમે નથી જોતા કે અલ્લાહે જે કંઈ છે, તે તમારા માટે વશ કરી દીધું છે? (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّרَ لَكُم مَّا فِي) 22:65; 31:20
- જે લોકો ઇન્કાર કરે છે, તેઓ કહેશે: આ તો સ્પષ્ટ જાદુ છે. (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- જ્યારે તેમને અમારી સ્પષ્ટ નિશાનીઓ સંભળાવવામાં આવે છે, તો કાફિરો કહે છે. (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- કાયમી બગીચાઓ, જેની નીચે નહેરો વહે છે, ત્યાં તેઓ હંમેશા રહેશે. (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- તે જે ઇચ્છે છે તે બનાવે છે; અલ્લાહ દરેક વસ્તુ પર સમર્થ છે. (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- જેથી તે તમારા પાપોને માફ કરે અને તમને નિર્ધારિત સમય સુધી મુહલત આપે. (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- શું તમે અમને તે વસ્તુથી રોકવા માંગો છો, જેની અમારા બાપદાદાઓ બંદગી કરતા હતા? (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- જ્યારે તમારા પાલનહારે ફરિશ્તાઓને કહ્યું: હું માટીમાંથી એક માનવી બનાવનાર છું. (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- તે જ છે જે પવનોને તેની કૃપા પહેલાં ખુશખબર આપનારા તરીકે મોકલે છે. (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- કહો: ધરતી પર ફરો અને જુઓ કે અંત કેવો થયો. (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- આકાશો અને ધરતીની રચનામાં અને રાત-દિવસના ફેરબદલમાં (નિશાનીઓ છે). (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- કોણ છે જે અલ્લાહને સારું ઉધાર આપે, જેથી તે તેને કેટલાક ગણા વધારે? (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- તો તેમની વચ્ચે અલ્લાહે જે ઉતાર્યું છે, તેના આધારે ફેંસલો કરો અને તેમની ઇચ્છાઓનું અનુસરણ ન કરો. (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- શું તેઓ એ સિવાય કંઈક બીજાની રાહ જુએ છે કે તેમની પાસે ફરિશ્તાઓ આવે, અથવા તમારા પાલનહારનો હુકમ આવે? (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- નિશ્ચિતપણે જે લોકો અલ્લાહ પર જૂઠું ખોટું રચે છે, તેઓ સફળ નહીં થાય. (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- જેમ કે ફિરઔનના લોકો અને તેમના પહેલાના લોકોની સ્થિતિ, તેઓએ અમારી નિશાનીઓને જૂઠી ઠરાવી. (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- અને તે ઈમાનવાળાઓને, જેઓ સત્કર્મો કરે છે, તેમને ખુશખબર આપે છે કે તેમના માટે બદલો છે. (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- અલ્લાહ પોતાના બંદાઓમાંથી જેને ઇચ્છે, રોજી પહોળી કરે છે અને સંકોચે છે. (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- અને તમે ગુપ્ત અને ખુલ્લા દરેક વસ્તુને જાણનાર તરફ પાછા ફેરવવામાં આવશો, પછી તે તમને જણાવશે જે કંઈ તમે કરતા હતા. (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- અને લોહીના સંબંધીઓ, તેમનામાંના કેટલાક બીજાઓ કરતાં અલ્લાહની કિતાબમાં વધુ નજીક છે. (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
cmds - Commands, Exhortations, Prohibitions, Instructions
- fard / wajib (فرض / واجب) — ફરજિયાત (કરવું જ જોઈએ; છોડવું પાપ)
- mustahabb / mandub (مستحب / مندوب) — ભલામણ કરેલ (કરવાથી સવાબ મળે, ન કરવાથી પાપ નહીં)
- mubah (مباح) — તટસ્થ / પરવાનગી આપેલ (ન સવાબ, ન પાપ)
- makruh (مكروه) — નાપસંદ (નિરુત્સાહિત, પણ કરવાથી પાપ નહીં)
- haram (حرام) — પ્રતિબંધિત (કરવું પાપ)
- halal (حلال, પરવાનગી આપેલ / કાયદેસર) — મુબાહ અને મુસ્તહાબ બંનેને આવરી લે છે — જે પ્રતિબંધિત નથી તે બધું
- ફક્ત અલ્લાહની ઉપાસના કરો અને તેની મદદ/સહાય માંગો. 1:5
- ફક્ત અલ્લાહની ઉપાસના કરો. 2:21
- અલ્લાહ સાથે કોઈને ભાગીદાર ન બનાવો. 2:22
- અલ્લાહ ક્ષમા કરનાર છે (તૌબા સ્વીકારનાર છે), તેણે આદમ (અલૈહિસ્સલામ) ની તૌબા સ્વીકારી. 2:37
- સત્યને અસત્ય સાથે ન ભેળવો અને સત્યને છુપાવો નહીં. 2:42
- સલાત (દૈનિક નમાઝ) પઢો અને ઝકાત (દાન) આપો. 2:43
- બીજાઓને સદાચારનો આદેશ આપો પછી જ્યારે તમે પોતે તેનું પાલન કરો. 2:44
- તમારા બધા કાર્યોમાં અલ્લાહની મદદ માંગો. 2:45
- ભ્રષ્ટાચારમાં ન પડો અને તેનો ફેલાવો ન કરો. 2:60
- લોકોને ઉપાસના સ્થળોએ જતા અટકાવો નહીં. 2:114
- મસ્જિદની પવિત્રતાનો આદર કરો. તમારા નમાઝના સ્થાનોને સ્વચ્છ અને પવિત્ર રાખો. 2:125
- અલ્લાહને યાદ કરો (નમાઝ પઢીને, તસ્બીહ કરીને વગેરે) અને તે તમને યાદ કરશે, અને તેનો આભાર માનો. 2:152
- મુશ્કેલીમાં ધીરજ રાખો. 2:153
- શેતાનના પગલાંને અનુસરો નહીં, જે ખુલ્લો દુશ્મન છે. 2:168
- કોઈનું આંધળું અનુકરણ ન કરો. 2:170
- બધી અમાનતોનું રક્ષણ કરો અને તેને પૂર્ણ કરો. તમારા ધાર્મિક ફરજો નિષ્ઠાપૂર્વક નિભાવો. તમારા સોગંદ અને વચનો પૂરા કરો. વચનોનું પાલન કરો, ખાસ કરીને અલ્લાહને આપેલા વચનો. જરૂરિયાતમંદોને ટેકો આપો અને મુશ્કેલીઓ દૂર કરો. એવા પાપો કરવાથી બચો જે દૈવી કૃપાના નુકશાન તરફ દોરી જાય છે. અહંકારને તમને અન્યાય તરફ ન લઈ જવા દો. 2:177
- કિસાસમાં (સજામાં સમાનતાનો કાયદો) તમારા માટે જીવન છે. 2:179
- રમઝાન મહિનામાં રોજા રાખો. મુત્તકીન (ધર્મપરાયણ) બનવા માટે નિયત રોજા રાખો. 2:183
- કુરઆનને માર્ગદર્શનના અંતિમ સ્ત્રોત તરીકે માન આપો. 2:185
- એકબીજાની સંપત્તિ અન્યાય રીતે ન ખાઓ અને શાસકો (તમારા કેસ રજૂ કરતા પહેલા) ને લાંચ ન આપો. 2:188
- બીજાઓ પર અત્યાચાર ન કરો, શબ્દોમાં કે કાર્યોમાં. ક્યારેય આક્રમણકાર તરીકે યુદ્ધ ન કરો, પરંતુ માત્ર સંરક્ષણ માટે. 2:190
- અનાથોનું રક્ષણ કરો. અનાથોના સંબંધમાં, તેમની સંપત્તિમાં પ્રામાણિકપણે કામ કરો અને તેમની સંપત્તિ ન ખાઓ. 2:220
- તૌબા કરો અને અલ્લાહની માફી માંગો. માસિક ધર્મ દરમિયાન જાતીય સંભોગ ન કરો. શુદ્ધતા જાળવો (શારીરિક અને આધ્યાત્મિક બંને રીતે). 2:222
- તમારા પરિવાર પ્રત્યે તમારી જવાબદારીઓ પૂર્ણ કરો. 2:233
- લાયકાતના આધારે નેતાઓ પસંદ કરો. 2:247
- ધર્મમાં કોઈ જબરદસ્તી નથી. 2:256
- દાનમાં સંપત્તિ ખર્ચ કરો. સંપત્તિ અને સમય બંનેમાં દાનશીલ બનો. 2:261
- તમારી ઉદારતાનો બડાઈ મારીને દાનને નિરર્થક ન બનાવો. 2:264
- શેતાન તમને ગરીબીની ધમકી આપે છે અને તમને અશ્લીલ કાર્યો (દુષ્કર્મો, ગેરકાયદેસર સંભોગ, પાપો) કરવાનો આદેશ આપે છે. 2:268
- જરૂરિયાતમંદોને શોધો અને તેમની મદદ કરો. 2:273
- વ્યાજ અને સૂદ સાથે સંકળાયેલા ન બનો. વ્યાજયુક્ત સંપત્તિ ન ખાઓ. રિબા (વ્યાજ) ન ખાઓ. 2:275
- જો દેવાદાર મુશ્કેલીમાં હોય તો ચૂકવણી માટે વધુ સમય આપો. 2:280
- વ્યવસાયિક વ્યવહારોમાં તમારા વચનનું પાલન કરો. તમારા નાણાકીય બાબતોમાં સત્યવાદી બનો. તમારી બધી પ્રતિબદ્ધતાઓમાં અખંડિતતા સાથે કાર્ય કરો. જ્યારે તમે નિશ્ચિત સમયગાળા માટે દેવું કરો, ત્યારે તેને લખો. જ્યારે પણ તમે વ્યાપારિક કરાર કરો ત્યારે સાક્ષીઓ રાખો. 2:282
- બધી અમાનતોનું રક્ષણ કરો અને તેને પૂર્ણ કરો. 2:283
- અવતરિત ગ્રંથો અને બધા પયગંબરો પર વિશ્વાસ કરો. 2:285
- અલ્લાહ કોઈને તેની ક્ષમતાથી વધુ બોજ નથી આપતો. સારા કાર્યોનો બદલો મળશે અને ખરાબ કાર્યોની સજા મળશે. ઈશ્વર કોઈને તેની ક્ષમતાથી વધુ બોજ નથી આપતો; આપણે પણ તેમ ન કરવું જોઈએ. મુશ્કેલીમાં પણ અલ્લાહની યોજના પર વિશ્વાસ રાખો. 2:286
- જે પ્રતિજ્ઞાઓ પૂરી કરે છે અને અલ્લાહનો ડર રાખે છે, તો અલ્લાહ ધર્મપરાયણોને પ્રેમ કરે છે. 3:76
- જો સમર્થ હો તો હજ (યાત્રા) કરો. 3:97
- વિભાજિત ન થાઓ. 3:103
- સદાચારનો આદેશ આપો અને દુષ્કર્મથી અટકાવો. તમારા સમાજમાં ન્યાયને પ્રોત્સાહિત કરો. બીજાઓને અલ્લાહની યાદ તરફ બોલાવો. 3:104
- મુમિનોએ અલ્લાહ પર જ ભરોસો રાખવો જોઈએ. 3:122
- રિબા (વ્યાજ) ન ખાઓ. 3:130
- દયા મેળવવા માટે અલ્લાહ અને તેના પયગંબરની આજ્ઞા પાળો. 3:132
- અલ્લાહ તે લોકોને પ્રેમ કરે છે જેઓ (અલ્લાહના માર્ગમાં — દાન, ખૈરાત વગેરે) સુખ અને દુઃખમાં ખર્ચ કરે છે, જેઓ ગુસ્સાને કાબૂમાં રાખે છે અને જેઓ લોકોને માફ કરે છે. 3:134
- ગુસ્સાને કાબૂમાં રાખો. તમારા ક્રોધને નિયંત્રિત કરો. 3:134
- બીજાઓની ભૂલોને માફ કરો અને ક્ષમા કરો. 3:135
- વાણીમાં કઠોર ન બનો. તમારાથી અલગ હોય તેવા લોકો સાથે ધીરજ રાખો. 3:159
- જો અલ્લાહ તમારી મદદ કરે તો કોઈ તમને હરાવી ન શકે; અને જો તે તમને છોડી દે તો તેના પછી કોણ તમારી મદદ કરી શકે? 3:160
- દરેક વ્યક્તિ મૃત્યુનો સ્વાદ ચાખશે. અને ફક્ત કયામતના દિવસે તમને તમારો પૂર્ણ બદલો મળશે. 3:185
- કુદરતના અજાયબીઓ અને આ વિશ્વની રચના વિશે ઊંડાણપૂર્વક વિચારો. જાણો કે ઈશ્વરે આ વિશ્વને અર્થ અને હેતુ સાથે બનાવ્યું છે. 3:191
- પુરુષો અને સ્ત્રીઓને તેમના કાર્યો માટે સમાન બદલો મળે છે. 3:195
- જેઓ તેમના પાલનહારથી ડરે છે, તેમના માટે (સ્વર્ગમાં) બગીચાઓ છે જેની નીચે નદીઓ વહે છે; ત્યાં તેઓ હંમેશા રહેશે, અલ્લાહ તરફથી આતિથ્ય તરીકે. 3:198
- દરેક કાર્યમાં હંમેશા અલ્લાહની પ્રસન્નતા મેળવવાનો પ્રયત્ન કરો. 3:200
- તમારા પાલનહારનો ડર રાખો, તેનાથી ડરો અને (સગપણના) સંબંધો ન તોડો. 4:1
- અનાથોને તેમની સંપત્તિ આપો અને (તમારી ખરાબ વસ્તુ) તેમની (સારી વસ્તુ) સાથે ન બદલો; અને તેમની સંપત્તિને (તમારી સંપત્તિમાં ઉમેરીને) ન ખાઓ. 4:2
- જે સ્ત્રીઓ સાથે તમે લગ્ન કરો તેમને તેમનો મહર (લગ્ન સમયે પતિ દ્વારા પત્નીને આપવામાં આવતી ફરજિયાત ભેટ) સ્વચ્છ હૃદયથી આપો. 4:4
- અનાથોના અધિકારોનું રક્ષણ કરો. 4:6
- મૃતકની સંપત્તિ તેના પરિવારના સભ્યો વચ્ચે વહેંચવી જોઈએ. સ્ત્રીઓને વારસાનો અધિકાર છે. 4:7
- અનાથોની સંપત્તિ અન્યાય રીતે ન ખાઓ. 4:10
- વારસા સંબંધી આદેશોનું પાલન કરો. 4:11
- સ્ત્રીઓને તેમની ઇચ્છા વિરુદ્ધ વારસામાં લેવી પ્રતિબંધિત છે, અને તેમની સાથે કઠોરતા ન કરવી જોઈએ. તેમની (પત્નીઓ) સાથે સન્માનપૂર્વક રહો. સ્ત્રીઓના અધિકારોનો આદર કરો અને તેનું પાલન કરો. તમારી પત્ની સાથે દયા અને કરુણા સાથે વર્તો. સ્ત્રીઓ સાથે સન્માન અને ન્યાય સાથે વર્તો. 4:19
- તમારા લોહીના સંબંધીઓ સાથે લગ્ન ન કરો. 4:23
- તમારી જાતને (અથવા એકબીજાને) ન મારો. નિશ્ચિત રીતે અલ્લાહ તમારા પર દયાળુ છે. એકબીજાની સંપત્તિ અન્યાય રીતે ન ખાઓ. 4:29
- જો તમે મોટા પાપો જે પ્રતિબંધિત છે તેનાથી બચો, તો અલ્લાહ તમારા (નાના) પાપોને દૂર કરશે અને તમને ઉમદા પ્રવેશ (સ્વર્ગ) માં દાખલ કરશે. 4:31
- જે બાબતોમાં અલ્લાહે તમારામાંના કેટલાકને બીજાઓ પર શ્રેષ્ઠતા આપી છે તેની ઇચ્છા ન કરો. ઈર્ષ્યા અને દ્વેષથી બચો. 4:32
- પુરુષો સ્ત્રીઓના રક્ષક અને સંચાલક છે, કારણ કે અલ્લાહે કેટલાકને બીજાઓ પર શ્રેષ્ઠતા આપી છે, અને કારણ કે તેઓ તેમના ધનમાંથી (તેમના ખર્ચ માટે) ખર્ચ કરે છે. પુરુષ પરિવારનો રક્ષક અને આધાર છે. 4:34
- અલ્લાહની ઉપાસના કરો અને તેની સાથે કોઈને ભાગીદાર ન બનાવો, માતા-પિતા, સગાંઓ, અનાથો, ગરીબો, પડોશી, સાથી, મુસાફર (જેને તમે મળો) અને તમારા હાથ નીચેના ગુલામો સાથે સદ્વ્યવહાર કરો. અલ્લાહને અહંકારી અને બડાઈખોર લોકો ગમતા નથી. બીજાઓ સાથે સારું કરો. નબળાઓ પર દયા કરો. કૌટુંબિક સંબંધો જાળવો અને સગાંઓનું સન્માન કરો. 4:36
- કંજૂસ ન બનો. 4:37
- અલ્લાહ માફ કરતો નથી કે તેની સાથે ભાગીદારો બનાવવામાં આવે, પરંતુ તે આ સિવાય જેને ઇચ્છે છે તેને માફ કરે છે. 4:48
- બીજાઓથી ઈર્ષ્યા ન કરો. 4:54
- અલ્લાહ તમને આદેશ આપે છે કે અમાનતો તેમના માલિકોને પરત કરો. જ્યારે તમે લોકો વચ્ચે ચુકાદો કરો ત્યારે ન્યાય સાથે ચુકાદો કરો. 4:58
- અલ્લાહ અને તેના પયગંબરની આજ્ઞા પાળો. તમારી વચ્ચે સત્તા ધરાવતા લોકોનું સન્માન કરો. 4:59
- નબળાઓ અને નિરાધાર લોકો પર અત્યાચાર ન કરો. 4:75
- તમને જે સારું મળે છે તે અલ્લાહ તરફથી છે; અને જે ખરાબ થાય છે તે તમારી જાત તરફથી છે. 4:79
- જે પયગંબર (મુહમ્મદ ﷺ) ની આજ્ઞા પાળે છે, તેણે અલ્લાહની આજ્ઞા પાળી. 4:80
- જે સારા કામની ભલામણ કરે છે તેને તેનો સવાબ મળશે; અને જે ખરાબ કામની ભલામણ કરે છે તેને તેનો બોજ ઉઠાવવો પડશે. 4:85
- કોઈ મુમિન માટે બીજા મુમિનને મારવું યોગ્ય નથી, સિવાય કે ભૂલથી. 4:92
- જે ઇરાદાપૂર્વક મુમિનને મારી નાખે, તેનો બદલો જહન્નમ છે, જ્યાં તે હંમેશા રહેશે. અલ્લાહનો કોપ અને અભિશાપ તેના પર છે, અને તેના માટે મોટી સજા તૈયાર કરવામાં આવી છે. 4:93
- જે અલ્લાહના માર્ગમાં (પોતાના ઘરેથી) હિજરત કરે છે, તે પૃથ્વી પર ઘણા આશ્રયસ્થાનો અને વિપુલતા શોધી કાઢશે. 4:100
- તમારી નમાઝો સમયસર પઢો. 4:103
- જેઓ તેમની અમાનતો સાથે વિશ્વાસઘાત કરે છે તેમનું સમર્થન કે વકીલ ન બનો. 4:105
- અલ્લાહની માફી માંગો, નિશ્ચિત રીતે અલ્લાહ માફ કરનાર, દયાળુ છે. 4:106
- હે ઇમાન લાવનારાઓ! ન્યાય માટે મક્કમ રહો, અલ્લાહ માટે સાક્ષી બનો, ભલે તે તમારી જાત વિરુદ્ધ હોય, અથવા તમારા માતા-પિતા, અથવા તમારા સગાંઓ વિરુદ્ધ હોય, તે શ્રીમંત હોય કે ગરીબ. ન્યાયમાં વિલંબ ન કરો; ખોટને સુધારવા માટે તાત્કાલિક કાર્ય કરો. 4:135
- દંભીઓ અલ્લાહને છેતરવાનો પ્રયાસ કરે છે, પરંતુ તે તેમને છેતરે છે. 4:142
- દંભીઓ નર્કના સૌથી નીચેના સ્તરમાં હશે; અને તમે તેમના માટે કોઈ મદદગાર શોધી શકશો નહીં. 4:145
- અલ્લાહને પસંદ નથી કે ખરાબ વાતો જાહેરમાં કહેવામાં આવે, સિવાય કે જેના પર અત્યાચાર થયો હોય. 4:148
- પયગંબરોને શુભ સમાચાર આપનારા અને ચેતવણી આપનારા તરીકે મોકલવામાં આવ્યા, જેથી પયગંબરો (આવ્યા) પછી લોકો પાસે અલ્લાહ સામે કોઈ બહાનું ન રહે. 4:165
- તમારા કરારો અને વચનો પૂરા કરો. 5:1
- સદાચાર અને ધર્મપરાયણતામાં એકબીજાની મદદ કરો, અને પાપ અને દુશ્મનાવટમાં મદદ ન કરો. 5:2
- મુરદાર, લોહી અને ડુક્કરનું માંસ ન ખાઓ. 5:3
- ન્યાયી બનો, બીજાઓ પ્રત્યેની દુશ્મનાવટ અને તિરસ્કારને તમને ન્યાયથી દૂર ન થવા દો. ન્યાયી બનો. જાણો કે ન્યાયી બનવું એ ધર્મપરાયણતાની નજીક છે. ન્યાયમાં વિલંબ ન કરો; ખોટને સુધારવા માટે તાત્કાલિક કાર્ય કરો. 5:8
- અલ્લાહ સુધી પહોંચવાના સાધનો શોધો અને તેના માર્ગમાં શક્તિ મુજબ જેહાદ કરો. જેથી તમે સફળ થાઓ. 5:35
- તમારા સોગંદ અને વચનો પૂરા કરો. 5:89
- નશીલા પદાર્થો અને દારૂથી દૂર રહો. નશીલા પદાર્થો (દારૂના તમામ પ્રકાર), જુગાર, અલ-અન્સાબ (પત્થરની વેદીઓ) અને અલ-અઝલામ (નસીબ અથવા નિર્ણય માટેના તીર) જે શેતાનના કાર્યની ગંદકી છે, તેનાથી સખત દૂર રહો. 5:90
- જ્યારે તમે હજ અથવા ઉમરાહ (યાત્રા) માટે એહરામની સ્થિતિમાં હોવ ત્યારે શિકાર ન કરો. 5:95
- એવી વસ્તુઓ વિશે પૂછો નહીં જે, જો તમને સ્પષ્ટ કરવામાં આવે તો, તમને મુશ્કેલી ઊભી કરી શકે. 5:101
- બીજાઓના દેવતાઓનું અપમાન ન કરો. તેઓ (અવિશ્વાસીઓ) અલ્લાહ ઉપરાંત જેની ઉપાસના કરે છે તેનું અપમાન ન કરો, નહીં તરીકે તેઓ અજ્ઞાનતાવશ અલ્લાહનું અપમાન કરે. 6:108
- જો તમે ધરતી પરના મોટાભાગના લોકોની આજ્ઞા પાળો, તો તેઓ તમને અલ્લાહના માર્ગથી ભટકાવી દેશે. તેઓ ફક્ત અનુમાનનું અનુસરણ કરે છે અને ફક્ત જૂઠું બોલે છે. 6:116
- (હે માનવો) બધા પ્રકારના પાપોને છોડી દો, ખુલ્લા અને છુપાયેલા. 6:120
- (હે ઇમાન લાવનારાઓ) જે (માંસ) પર અલ્લાહનું નામ લેવામાં ન આવ્યું હોય (પ્રાણીના વધ સમયે) તે ન ખાઓ. 6:121
- અલ્લાહ જેને માર્ગદર્શન આપવા ઈચ્છે છે, તેનો છાતી ઇસ્લામ માટે ખોલી દે છે; અને જેને તે પથભ્રષ્ટ કરવા ઈચ્છે છે, તેનો છાતી સાંકડો અને ભીંસાયેલો બનાવી દે છે. 6:125
- ખર્ચમાં સંયમ રાખો અને ફજૂલખર્ચીથી બચો. બધા જીવોના અધિકારોનું રક્ષણ કરો. 6:141
- અલ્લાહ સાથે કોઈને ભાગીદાર ન બનાવો, માતા-પિતા સાથે સદ્વ્યવહાર કરો, ગરીબીના ડરથી તમારા બાળકોને ન મારો, અશ્લીલ કાર્યોની નજીક ન જાઓ, જેનો અલ્લાહે ખૂન પ્રતિબંધિત કર્યો છે તેને ન્યાયસંગત કારણ સિવાય ન મારો. 6:151
- પ્રામાણિક બનો; તમારા કોઈપણ વ્યવહારમાં છેતરપિંડી ન કરો. અનાથની સંપત્તિની નજીક ન જાઓ, સિવાય કે તેને સુધારવા માટે, ન્યાય સાથે પૂર્ણ માપ અને પૂર્ણ વજન આપો, જ્યારે તમે વાત કરો ત્યારે સત્ય બોલો, ભલે તે નજીકના સગાને લગતું હોય, અને અલ્લાહની પ્રતિજ્ઞા પૂરી કરો. 6:152
- સીધો માર્ગ અપનાવો અને (બીજા) માર્ગો ન અપનાવો, કારણ કે તેઓ તમને તેમના માર્ગથી અલગ કરી દેશે. 6:153
- (હે મુહમ્મદ ﷺ) કહો: "નિશ્ચિત રીતે, મારી નમાઝ, મારી કુરબાની, મારું જીવન અને મારું મૃત્યુ વિશ્વના પાલનહાર અલ્લાહ માટે છે." 6:162
- અહંકારી ન બનો. 7:13
- શેતાન તમને છેતરવા ન દો. 7:27
- (હે મુહમ્મદ ﷺ) કહો: "મારા પાલનહારે ન્યાયનો આદેશ આપ્યો છે…" 7:29
- બધી બાબતોમાં અલ્લાહે નિર્ધારિત કરેલી મર્યાદાઓનું પાલન કરો. વાણી અને કાર્યોમાં અતિરેક ન કરો. ખાઓ-પીઓ પણ ફજૂલખર્ચી ન કરો. નમાઝના સમયે સારા કપડાં પહેરો. 7:31
- અલ્લાહે આકાશો અને પૃથ્વીને છ દિવસમાં બનાવ્યાં, પછી તે અર્શ (સિંહાસન) પર સ્થિત થયો (તેની મહાનતા માટે યોગ્ય રીતે). 7:54
- તમારા પાલનહારને નમ્રતા અને છુપાઈને પ્રાર્થના કરો. તે અતિરેક કરનારાઓને પસંદ નથી કરતો. 7:55
- અને પૃથ્વીને સુધાર્યા પછી ત્યાં ફસાદ ન કરો, અને તેને ડર અને આશા સાથે પ્રાર્થના કરો. 7:56
- પરંતુ જેમણે દુષ્કર્મો કર્યા અને પછી તેનાથી પશ્ચાત્તાપ કર્યો અને ઇમાન લાવ્યા, તો નિશ્ચિત રીતે તમારો પાલનહાર તે પછી માફ કરનાર, દયાળુ છે. 7:153
- (હે મુહમ્મદ ﷺ) કહો: "હે લોકો! નિશ્ચિત રીતે હું તમારા બધા તરફ અલ્લાહનો પયગંબર છું…" 7:158
- અને (બધા) ખૂબસૂરત નામો અલ્લાહ માટે છે, તેથી તે દ્વારા તેને પુકારો, અને જેઓ તેમના નામોમાં ભ્રષ્ટાચાર કરે છે તેમને છોડી દો… 7:180
- અલ્લાહ જેને પથભ્રષ્ટ કરે છે, તેને કોઈ માર્ગદર્શક નથી; અને તે તેમને તેમના અતિરેકમાં આંધળા ભટકવા દે છે. 7:186
- ક્ષમા બતાવો, સદાચારનો આદેશ આપો, અને અજ્ઞાનીઓથી મોં ફેરવો (એટલે કે તેમને સજા ન કરો). 7:199
- બીજાઓની ભૂલોને માફ કરો. 7:199
- અને જો શેતાન તરફથી કોઈ ખરાબ ઉશ્કેરાટ તમને થાય, તો અલ્લાહનો આશરો માંગો. નિશ્ચિત રીતે તે સાંભળનાર, જાણનાર છે. 7:200
- મુમિનો ફક્ત તે જ છે કે જેમના દિલોમાં અલ્લાહનું નામ લેવાય ત્યારે ભય પેદા થાય છે, અને જ્યારે તેમને તેની આયતો પઢીને સંભળાવવામાં આવે છે, ત્યારે તે તેમની ઇમાનમાં વધારો કરે છે… 8:2
- અલ્લાહ અને તેના પયગંબર સાથે વિશ્વાસઘાત ન કરો, અને જાણી-જોઈને તમારી અમાનતો (અને અલ્લાહે તમને જે આદેશો આપ્યા છે) સાથે વિશ્વાસઘાત ન કરો. 8:27
- જો તમે અલ્લાહની આજ્ઞા પાળો અને તેનો ડર રાખો, તો તે તમને ફુરકાન (સત્ય અને અસત્ય વચ્ચે તફાવત કરવાનો માપદંડ, અથવા દરેક મુશ્કેલીમાંથી બહાર નીકળવાનો માર્ગ) આપશે. 8:29
- જે લોકો ઇન્કાર કરે છે, તેઓ પોતાની સંપત્તિ અલ્લાહના માર્ગથી (લોકોને) રોકવા માટે ખર્ચ કરે છે, અને તેઓ તે ખર્ચ કરતા રહેશે; પરંતુ અંતે તે તેમના માટે અફસોસનું કારણ બનશે. 8:36
- જે લોકોએ ઇન્કાર કર્યો છે તેમને કહો, જો તેઓ (ઇન્કારથી) રોકાઈ જાય, તો તેમના ભૂતકાળને માફ કરવામાં આવશે. પરંતુ જો તેઓ (તેની તરફ) પાછા ફરે, તો તેમની પહેલાના (સજા પામેલા) લોકોના દાખલા પહેલાથી જ આપવામાં આવી ચૂક્યા છે (ચેતવણી તરીકે). 8:38
- જ્યારે તમે (શત્રુ) સેનાનો સામનો કરો, ત્યારે મક્કમ રહો અને અલ્લાહના નામનું ઘણું સ્મરણ કરો (જીભ અને મન બંને દ્વારા), જેથી તમે સફળ થાઓ. 8:45
- જે લોકો પોતાના ઘરેથી ઘમંડ અને લોકોને બતાવવા માટે બહાર નીકળ્યા અને (લોકોને) અલ્લાહના માર્ગથી રોક્યા તેમના જેવા ન બનો. 8:47
- અલ્લાહ કોઈ પણ લોકોને આપેલી નેમતને બદલતો નથી, જ્યાં સુધી તેઓ પોતે જે તેમનામાં છે તેને બદલી ન દે. 8:53
- અલ્લાહ પાસે સૌથી ખરાબ જીવજંતુઓ તે છે જેઓ ઇન્કાર કરે છે. 8:55
- અલ્લાહ તેના પર ઇમાન લાવનારાઓના દિલો વચ્ચે પ્રેમ અને સ્નેહ પેદા કરે છે. 8:63
- જેઓ શરણ માંગે છે તેમનું રક્ષણ કરો અને મદદ કરો. 9:6
- મુશરિકો માટે અલ્લાહની મસ્જિદોની જાળવણી કરવી યોગ્ય નથી. 9:17
- તેઓ (ઇન્કાર કરનારાઓ, યહૂદીઓ અને ખ્રિસ્તીઓ) પોતાના મોં વડે અલ્લાહના પ્રકાશ (જેની સાથે મુહમ્મદ ﷺ મોકલવામાં આવ્યા — ઇસ્લામિક એકેશ્વરવાદ) ને ઓલવવા માંગે છે, પરંતુ અલ્લાહ તેના પ્રકાશને પૂર્ણ કરવા સિવાય બીજું કંઈ કરવા દેતો નથી, ભલેને કાફિરોને તે ગમતું ન હોય. 9:32
- સદકાત (એટલે કે ઝકાત) ફક્ત આ માટે છે: 1) ફકીરો (ગરીબો) માટે, 2) મિસ્કીનો (અભાવગ્રસ્તો) માટે, 3) તેના સંગ્રહ માટે નિયુક્ત લોકો માટે, 4) જેમના દિલ ઇસ્લામ તરફ વળ્યા હોય તેમના માટે, 5) કેદીઓની મુક્તિ માટે, 6) દેવાદારો માટે, 7) અલ્લાહના માર્ગમાં (મુજાહિદીન માટે) અને 8) મુસાફર માટે. 9:60
- જે કોઈ અલ્લાહ અને તેના પયગંબર (ﷺ) ની વિરુદ્ધ જાય અને દુશ્મનાવટ કરે, તો તેના માટે જહન્નમની આગ છે, જેમાં તે હંમેશા રહેશે. તે મોટી બદનામી છે. 9:63
- દંભી પુરુષો અને દંભી સ્ત્રીઓ એકબીજા જેવા છે. તેઓ અલ્લાહને ભૂલી ગયા, તેથી તેમણે પણ તેમને ભૂલી દીધા. 9:67
- પવિત્રતા તરફ પ્રયત્ન કરો. મસ્જિદની પવિત્રતાનો આદર કરો. 9:108
- (પયગંબર અને મુમિનો માટે) મુશરિકો માટે અલ્લાહની માફી માંગવી યોગ્ય નથી, ભલે તેઓ સગાંઓ હોય, જ્યારે તેમને સ્પષ્ટ થઈ ગયું હોય કે તેઓ નર્કવાસી છે (કારણ કે તેઓ ઇન્કારની સ્થિતિમાં મૃત્યુ પામ્યા). 9:113
- અલ્લાહ પર જૂઠું બાંધનાર અથવા તેની આયતોને નકારનાર કરતાં વધુ અત્યાચારી કોણ છે? નિશ્ચિત રીતે, ગુનેગારો ક્યારેય સફળ થશે નહીં! 10:17
- તેઓ અલ્લાહ ઉપરાંત એવી વસ્તુઓની ઉપાસના કરે છે જે તેમને નુકસાન કે ફાયદો પહોંચાડી શકતી નથી, અને તેઓ કહે છે: "આ અલ્લાહ પાસે અમારા ભલામણકર્તાઓ છે." કહો: "શું તમે અલ્લાહને એવી વસ્તુથી જાણ કરો છો જે તે આકાશો અને પૃથ્વીમાં જાણતો નથી?" તે પવિત્ર છે અને તેઓ જેને ભાગીદાર બનાવે છે તેનાથી ઉચ્ચ છે! 10:18
- દુષ્કર્મનો બદલો તેના જેવું દુષ્કર્મ છે. 10:27
- આ છે અલ્લાહ, તમારો સાચો પાલનહાર. તો સત્ય પછી ભટકવા સિવાય શું છે? તો પછી તમે ક્યાં ફેરવાઈ જાઓ છો? 10:32
- તેમાંના મોટાભાગના લોકો ફક્ત અનુમાનનું અનુસરણ કરે છે. નિશ્ચિત રીતે અનુમાન સત્યની સામે કોઈ ફાયદો નથી આપતું. 10:36
- નિશ્ચિત રીતે! અલ્લાહ લોકો પર થોડું પણ અત્યાચાર કરતો નથી; પરંતુ લોકો પોતે પોતાના પર અત્યાચાર કરે છે. 10:44
- જાણો કે અલ્લાહની કૃપા માણસ ભેગી કરી શકે અથવા સંગ્રહી શકે તે બધા કરતાં વધુ સારી છે. 10:58
- જેઓ અલ્લાહની આયતોને નકારે છે તેમના જેવા ન બનો, નહીં તો તમે નુકસાન ઉઠાવનારાઓમાં થશો. 10:95
- જો અલ્લાહ તમને કોઈ પીડા પહોંચાડે, તો તેને દૂર કરનાર તેના સિવાય કોઈ નથી; અને જો તે તમારા માટે સારું ઈચ્છે, તો તેની કૃપાને કોઈ દૂર કરી શકે તેમ નથી, તે તેના બંદાઓમાંથી જેને ઇચ્છે છે તેને પહોંચાડે છે. 10:107
- પૃથ્વી પર કોઈ પણ જીવજંતુ એવી નથી જેનું રોજી અલ્લાહના પર ન હોય. અને તે તેના રહેવાની જગ્યા અને તેના સંગ્રહસ્થાન (ગર્ભાશય, કબર વગેરે) ને જાણે છે. 11:6
- જો આપણે માણસને આપણી તરફથી કૃપાનો સ્વાદ ચખાડીએ, પછી તેને તેની પાસેથી છીનવી લઈએ, તો નિશ્ચિત રીતે તે નિરાશ અને કૃતઘ્ન બની જાય છે. 11:9
- જે કોઈ દુનિયાના જીવન અને તેની સુંદરતાને ઈચ્છે છે, અમે તેમને તેમાં તેમના કાર્યોનો સંપૂર્ણ બદલો આપીશું અને તેમાં તેમને કોઈ ઘટાડો કરવામાં આવશે નહીં. 11:15
- અમે તેમના પર અત્યાચાર કર્યો નથી, પરંતુ તેમણે પોતે પોતાના પર અત્યાચાર કર્યો. અને અલ્લાહ ઉપરાંત તેઓ જેને પુકારતા હતા તેમના દેવતાઓએ, જ્યારે તમારા પાલનહારનો આદેશ આવ્યો, ત્યારે તેમને કોઈ ફાયદો ન પહોંચાડ્યો, અને તેઓએ તેમના વિનાશ સિવાય કંઈ વધાર્યું નહીં. 11:101
- જે દિવસે તે (સજા) આવશે, તેના (અલ્લાહ) ની પરવાનગી વિના કોઈ બોલશે નહીં. તેમાંથી કેટલાક દુર્ભાગ્યશાળી અને (કેટલાક) ભાગ્યશાળી હશે. 11:105
- જેઓ દુર્ભાગ્યશાળી છે, તેઓ નર્કમાં હશે, જ્યાં તેમને ઊંડા શ્વાસ અને કકળાટ થશે. 11:106
- તેઓ ત્યાં હંમેશા રહેશે, જ્યાં સુધી આકાશો અને પૃથ્વી રહેશે, સિવાય કે તમારો પાલનહાર જે ઇચ્છે. નિશ્ચિત રીતે તમારો પાલનહાર જે ઇચ્છે છે તે કરે છે. 11:107
- અને જેઓ ભાગ્યશાળી છે, તેઓ સ્વર્ગમાં હશે, ત્યાં હંમેશા રહેશે, જ્યાં સુધી આકાશો અને પૃથ્વી રહેશે, સિવાય કે તમારો પાલનહાર જે ઇચ્છે, એક અવિરત ભેટ તરીકે. 11:108
- અત્યાચારીઓ તરફ ઝુકાવ ન કરો, નહીં તો આગ તમને સ્પર્શી જશે, અને અલ્લાહ સિવાય તમારો કોઈ રક્ષક નહીં હોય, અને પછી તમારી મદદ કરવામાં નહીં આવે. 11:113
- દિવસના બે છેડે અને રાત્રિના કેટલાક કલાકોમાં નમાઝ પઢો (એટલે કે 5 વખતની નમાઝ). સારા કાર્યો ખરાબ કાર્યોને (એટલે કે નાના પાપોને) દૂર કરે છે. 11:114
- આકાશો અને પૃથ્વીનું ગુપ્ત જ્ઞાન અલ્લાહ માટે છે, અને બધી બાબતો તેની તરફ જ પરત કરવામાં આવે છે (નિર્ણય માટે). 11:123
- આદેશ (અથવા ચુકાદો) ફક્ત અલ્લાહ માટે છે. તેણે આદેશ આપ્યો છે કે તમે તેના સિવાય કોઈની ઉપાસના ન કરો (એકેશ્વરવાદ), તે સીધો ધર્મ છે, પરંતુ મોટાભાગના લોકો જાણતા નથી. 12:40
- અલ્લાહની દયાથી ક્યારેય નિરાશ ન થાઓ. 12:87
- અને મોટાભાગના લોકો ઇમાન લાવશે નહીં, ભલે તમે ખૂબ જ ઇચ્છા કરો. 12:103
- અને તેમાંથી મોટાભાગના લોકો અલ્લાહ પર ઇમાન નથી રાખતા, સિવાય કે તેની સાથે ભાગીદારો બનાવીને (એટલે કે તેઓ મુશરિક છે). 12:106
- તે (કુરઆન) કોઈ બનાવટી વાત નથી, પરંતુ તે પહેલાના (તૌરાત, ઇંજીલ અને અન્ય ગ્રંથો) ની પુષ્ટિ છે અને દરેક વસ્તુનું વિગતવાર સ્પષ્ટીકરણ છે, અને ઇમાન લાવનારા લોકો માટે માર્ગદર્શન અને કૃપા છે. 12:111
- અલ્લાહ જેને ઇચ્છે તેને રોજી વધારે છે અને (જેને ઇચ્છે) ઘટાડે છે. 13:26
- ઝિક્ર દ્વારા અલ્લાહને વારંવાર યાદ કરો. જેઓ અલ્લાહ પર ઇમાન લાવે છે, તેમના દિલ તેને યાદ કરવાથી શાંતિ મેળવે છે. 13:28
- જેઓ ઇમાન લાવે છે અને સત્કર્મો કરે છે, તેમને આનંદ અને માનસિક શાંતિ આપવામાં આવે છે. 13:29
- જેઓ આખિરત (પરલોક) ને બદલે દુનિયાના જીવનને પ્રાધાન્ય આપે છે, અને અલ્લાહના માર્ગ (ઇસ્લામ) થી (લોકોને) રોકે છે અને તેમાં વક્રતા શોધે છે — તે લોકો દૂરના પથભ્રષ્ટતામાં છે. 14:3
- ઉપાસનામાં નમ્રતા અને કૃતજ્ઞતા રાખો. 14:7
- જેઓ પોતાના પાલનહારનો ઇન્કાર કરે છે તેમનું ઉદાહરણ રાખ જેવું છે, જેના પર વાવાઝોડાવાળા દિવસે પવન જોરથી ફૂંકાય છે; તેઓને પોતે કમાયેલામાંથી કંઈ મળતું નથી. 14:18
- અલ્લાહ મુમિનોને દુનિયામાં (એટલે કે તેઓ ફક્ત અલ્લાહની ઉપાસના કરતા રહેશે) અને આખિરતમાં પાકા વચન સાથે સ્થિર રાખશે. 14:27
- અલ્લાહ અત્યાચારીઓ (મુશરિકો, અન્યાયીઓ વગેરે) ના કાર્યોથી બેખબર છે એમ ન સમજો; પરંતુ તે તેમને એક એવા દિવસ સુધી મુહલત આપે છે જ્યારે આંખો ડરથી ખુલ્લી થઈ જશે. 14:42
- જેથી અલ્લાહ દરેક વ્યક્તિને તેની કમાણી પ્રમાણે બદલો આપે. નિશ્ચિત રીતે અલ્લાહ હિસાબ લેવામાં ઝડપી છે. 14:51
- અને નિશ્ચિત રીતે અમે માણસને સખત કાળી કાદવમાંથી બનાવ્યો. 15:26
- અને જિન્નાતોને અમે તે પહેલાં ધુમાડા વગરની આગમાંથી બનાવ્યા. 15:27
- તેના (નર્કના) સાત દરવાજા છે, દરેક દરવાજા માટે (ખાસ) પાપીઓનો વર્ગ છે. 15:44
- તેણે માણસને ટીપાં (પુરુષ અને સ્ત્રીના જનનાંગોના મિશ્રણ) માંથી બનાવ્યો, પછી તે (માણસ) ખુલ્લો શત્રુ બની જાય છે. 16:4
- અને ઢોર-ઢાંખર, તેણે તેને તમારા માટે બનાવ્યો; તેમાં તમારા માટે ગરમી (ગરમ કપડાં) અને ઘણા ફાયદા છે, અને તેમાંથી તમે ખાઓ છો. 16:5
- અને (તેણે બનાવ્યા) ઘોડા, ખચ્ચર અને ગધેડા, તમારા સવારી અને શણગાર માટે. અને તે એવી (બીજી) વસ્તુઓ બનાવે છે જે તમે જાણતા નથી. 16:8
- તે તે છે જે આકાશમાંથી પાણી (વરસાદ) વરસાવે છે; તેમાંથી તમે પીવો છો અને તેનાથી વનસ્પતિ ઊગે છે જેના પર તમે તમારા ઢોરને ચરાવો છો. 16:10
- તે તે છે જેણે સમુદ્રને (તમારા) કાબૂમાં આપ્યો, જેથી તમે તેમાંથી તાજું માંસ (માછલી) ખાઓ અને તેમાંથી દાગીના કાઢો જે તમે પહેરો છો. 16:14
- તેણે પૃથ્વીમાં સ્થિર પર્વતો નાખ્યા, જેથી તે તમને લઈને હલેશે નહીં, અને નદીઓ અને રસ્તાઓ, જેથી તમે માર્ગદર્શન મેળવો. 16:15
- શું જે સર્જન કરે છે, તે જે સર્જન નથી કરતો તેના જેવો છે? શું તમે યાદ નહીં કરો? 16:17
- જો તમે અલ્લાહની કૃપાઓની ગણતરી કરો તો તમે તેની ગણતરી ક્યારેય કરી શકતા નથી. 16:18
- અલ્લાહ જાણે છે જે તમે છુપાવો છો અને જે તમે જાહેર કરો છો. 16:19
- જેમને તેઓ (મુશરિકો) અલ્લાહ ઉપરાંત પુકારે છે, તેઓએ કંઈ બનાવ્યું નથી, પરંતુ તેઓ પોતે બનાવવામાં આવ્યા છે. 16:20
- (તેઓ) મૃત, નિર્જીવ છે, અને તેઓને ખબર નથી કે ક્યારે તેઓ ઉઠાવવામાં આવશે. 16:21
- અમારો શબ્દ જ્યારે અમે કોઈ વસ્તુ ઇચ્છીએ છીએ, તો અમે તેને માત્ર એટલું જ કહીએ છીએ: "થઈ જા!" અને તે થઈ જાય છે. 16:40
- જેઓ ખરાબ કાવતરાં રચે છે, શું તેઓ સુરક્ષિત છે કે અલ્લાહ તેમને પૃથ્વીમાં ધસાવી દેશે, અથવા તેમના પર સજા એવી દિશામાંથી આવશે જેનો તેમને અંદાજો પણ ન હોય? 16:45
- તમારી પાસે જે પણ નેમત અને સારી વસ્તુઓ છે, તે અલ્લાહ તરફથી છે. પછી જ્યારે તમને મુશ્કેલી આવે છે, ત્યારે તમે તેની જ પાસે ચીસો પાડીને મદદ માંગો છો. 16:53
- પછી જ્યારે તે તમારી પાસેથી મુશ્કેલીને દૂર કરે છે, ત્યારે તમારામાંથી કેટલાક તેમના પાલનહાર (અલ્લાહ) સાથે ભાગીદારો બનાવે છે. 16:54
- ઢોર-ઢાંખરમાં તમારા માટે શિક્ષણ છે. અમે તમને તેમના પેટની અંદરની વસ્તુ, વિષ્ટા અને લોહી વચ્ચેથી, શુદ્ધ દૂધ પીવડાવીએ છીએ, જે પીનારાઓ માટે સ્વાદિષ્ટ છે. 16:66
- તો અલ્લાહ માટે ઉપમાઓ ન આપો (કારણ કે તેના સમાન કંઈ નથી, ન તો તે કંઈ સમાન છે). નિશ્ચિત રીતે અલ્લાહ જાણે છે, અને તમે જાણતા નથી. 16:74
- જાણો કે અલ્લાહે લોકોને સાંભળવાની, જોવાની, બુદ્ધિ અને લાગણીઓ આપી છે, જેથી તેઓ કૃતજ્ઞ બની શકે. 16:78
- લોભ અને કંજૂસાઈથી દૂર રહો. 16:97
- જ્યારે તમે કુરઆન વાંચવા ઈચ્છો, ત્યારે શેતાન, ધિક્કારપાત્રથી અલ્લાહનો આશ્રો માંગો. 16:98
- જાણો કે અજ્ઞાનતાવશ કરવામાં આવેલું ખોટું, જો વ્યક્તિ તૌબા કરે અને પોતાને સુધારે, તો તેને માફ કરવામાં આવે છે. 16:119
- (હે મુહમ્મદ ﷺ) તમારા પાલનહારના માર્ગ (ઇસ્લામ) તરફ હિકમત અને સારા ઉપદેશ સાથે બોલાવો, અને તેમની સાથે શ્રેષ્ઠ રીતે દલીલ કરો. બીજાઓને અલ્લાહના માર્ગ તરફ બોલાવવો હિકમત અને સૌજન્ય સાથે થવો જોઈએ. 16:125
- અલ્લાહ તેમની સાથે છે જેઓ તેનો ડર રાખે છે (જેઓ તેના પ્રત્યે તેમની ફરજ નિભાવે છે) અને જેઓ સદાચારી છે. 16:128
- આ કુરઆન તે માર્ગ બતાવે છે જે સૌથી સીધો અને ન્યાયી છે. 17:9
- કોઈ બીજાનો ભાર (પાપ) ઉઠાવશે નહીં. 17:15
- જે કોઈ આખિરત (પરલોક) ને ઈચ્છે છે અને તેના માટે યોગ્ય પ્રયત્ન કરે છે, તે મુમિન હોય, તો તેવા લોકોના પ્રયત્નની કદર કરવામાં આવશે અને બદલો આપવામાં આવશે (અલ્લાહ તરફથી). 17:19
- તમારા માતા-પિતાનું સન્માન કરો અને તેમની સાથે દયાથી વર્તો. માતા-પિતા પ્રત્યે ફરજનિષ્ઠ બનો. માતા-પિતાને અપમાનજનક શબ્દ ન કહો. અને તમારા પાલનહારે આદેશ આપ્યો છે કે તમે તેના સિવાય કોઈની ઉપાસના ન કરો. અને માતા-પિતા સાથે સદ્વ્યવહાર કરો. જો તેમનામાંથી કોઈ એક અથવા બંને તમારી જિંદગીમાં વૃદ્ધાવસ્થા પ્રાપ્ત કરે, તો તેમને "ઉફ" સુધ્ધાં ન કહો, ન તેમને ધમકાવો, પરંતુ તેમની સાથે સન્માનપૂર્ણ શબ્દોમાં વાત કરો. 17:23
- અને તેમના માટે નમ્રતા અને દયાના પાંખ નીચાં કરો, અને કહો: "હે મારા પાલનહાર! તેમના પર દયા કરો, જેમ કે તેઓએ મારા બાળપણમાં મને ઉછેર્યો." 17:24
- નિશ્ચિત રીતે ફજૂલખર્ચી કરનારાઓ શેતાનના ભાઈઓ છે, અને શેતાન તેના પાલનહારનો કૃતઘ્ન છે. 17:27
- પૈસાની ફજૂલખર્ચી ન કરો. 17:29
- ગરીબીના ડરથી તમારા બાળકોને ન મારો. 17:31
- વ્યભિચારની નજીક ન જાઓ. લગ્નની પવિત્રતા જાળવો અને વ્યભિચારથી દૂર રહો. 17:32
- જ્યારે માપો ત્યારે પૂર્ણ માપ આપો, અને સીધા ત્રાજવાથી તોલો. તે સારું છે (લાભદાયક) અને અંતે ઉત્તમ છે. 17:35
- (હે માણસ) જે વસ્તુનું તમને જ્ઞાન ન હોય તેનું અનુસરણ ન કરો (દાખલા તરીકે, કોઈ કહે: "મેં જોયું," જ્યારે તેણે જોયું ન હોય, અથવા "મેં સાંભળ્યું," જ્યારે તેણે સાંભળ્યું ન હોય). 17:36
- નમ્ર બનો અને અહંકારી ન બનો. પૃથ્વી પર ઘમંડ સાથે ન ચાલો. નિશ્ચિત રીતે તમે પૃથ્વીને ફાડી શકતા નથી, અને ન તો તમે પર્વતોની ઊંચાઈ સુધી પહોંચી શકો છો. 17:37
- તમારો પાલનહાર તમને સૌથી સારી રીતે જાણે છે; જો તે ઇચ્છે તો તમારા પર દયા કરશે, અથવા જો તે ઇચ્છે તો તમને સજા કરશે. 17:54
- જે આ દુનિયામાં આંધળો છે (એટલે કે અલ્લાહની નિશાનીઓ જોતો નથી અને તેના પર ઇમાન નથી રાખતો), તે આખિરતમાં પણ આંધળો હશે, અને માર્ગથી વધુ ભટકાયેલો હશે. 17:72
- નિર્ધારિત નમાઝના સમયનું પાલન કરો. 17:78
- અમે આ કુરઆનમાં લોકો માટે દરેક પ્રકારના દાખલાઓ સ્પષ્ટ કરી દીધા છે, પરંતુ મોટાભાગના લોકો (સત્ય) નકારે છે અને ફક્ત ઇન્કાર જ સ્વીકારે છે. 17:89
- અમે આ કુરઆનમાં લોકો માટે દરેક પ્રકારના દાખલાઓ રજૂ કર્યા છે. પરંતુ માણસ દરેક વસ્તુ કરતાં વધુ ઝઘડાખોર છે. 18:54
- તેમનો બદલો જહન્નમ છે; કારણ કે તેઓએ ઇન્કાર કર્યો અને મારી આયતો અને મારા પયગંબરોની મજાક અને ઠેકડી ઉડાવી. 18:106
- અલ્લાહ (ની મહાનતા) માટે તે યોગ્ય નથી કે તે સંતાન રાખે (આ ખ્રિસ્તીઓના અલ્લાહ પરના અપવાદનો સંકેત છે, જે કહે છે કે ઈસા (યેશુ) અલ્લાહના પુત્ર છે). તે પવિત્ર છે (અને જેને તેઓ ભાગીદાર બનાવે છે તેનાથી ઉચ્ચ છે). 19:35
- લોકો સાથે નમ્રતાપૂર્વક વાત કરો. 20:44
- સત્કર્મોમાં એકબીજા સાથે સ્પર્ધા કરો. 21:90
- નિરર્થક વાતોથી દૂર રહો. 23:3
- તમારી શરમનું રક્ષણ કરો. 23:5
- તમારા હૃદયને પાપી વલણોથી બચાવો. 23:97
- બીજાઓને માફ કરો અને તેમની ભૂલોને ક્ષમા કરો. 24:22
- બીજાઓની ગોપનીયતાનો આદર કરો, ખાસ કરીને તેમના ઘરોમાં. પડોશીઓના અધિકારો પૂર્ણ કરો. 24:27
- (પુરુષો અને સ્ત્રીઓ બંને) નજર નીચી રાખો. તમારી શરમ અને પવિત્રતાનું રક્ષણ કરો. 24:30
- પોશાક અને વર્તનમાં શરમનું પાલન કરો. 24:31
- જાણો કે અલ્લાહ તે લોકોને સુરક્ષા અને શાંતિ આપે છે જેઓ તેની ઉપાસના કરે છે અને સત્કર્મો કરે છે. 24:55
- પરવાનગી વિના માતા-પિતાના ખાનગી રૂમમાં પ્રવેશ ન કરો. 24:58
- નમ્ર અને વિનમ્ર બનો. 25:63
- જૂઠી સાક્ષી અને છેતરપિંડીથી દૂર રહો. 25:72
- આખિરતના બદલા માટે પ્રયત્ન કરો, પરંતુ આ દુનિયાના કાર્યોની ઉપેક્ષા ન કરો. 28:77
- અલ્લાહ સિવાય બીજા કોઈ ઉપાસ્યને ન પુકારો. 28:88
- સમલૈંગિકતામાં સામેલ ન થાઓ. 29:29
- તમારા બધા પ્રયાસોમાં ઉત્તમતા માટે પ્રયત્ન કરો. 29:69
- નમાઝ પઢો અને ઝકાત આપો. 31:4
- સદાચારનો આદેશ આપો અને દુષ્કર્મથી અટકાવો. 31:17
- તમારા વર્તનમાં અહંકારથી દૂર રહો. નકામી વાતોમાં સમય બગાડો નહીં. 31:18
- ચાલવા અને બોલવાના અવાજમાં સંયમ રાખો. 31:19
- પયગંબર મુહમ્મદના ઉદાહરણનું અનુસરણ કરો. 33:21
- સ્ત્રીઓએ તેમની સુંદરતા અને શણગાર દેખાડવા અથવા દિખાવો નહીં. 33:33
- દરેક પરિસ્થિતિમાં સત્ય બોલો. 33:70
- ચિંતન દ્વારા શાણપણ અને સમજણ શોધો. 38:29
- કુરઆનના આદેશોનું પાલન કરો. 39:23
- અલ્લાહ બધા પાપોને માફ કરે છે જ્યારે પાપી તૌબા કરે છે અને તેની તરફ વળે છે. 39:53
- અલ્લાહ માટે નિષ્ઠાવાન દુઆ (પ્રાર્થના) કરો. 40:60
- દુષ્કર્મને તેનાથી સારાથી દૂર કરો. 41:34
- બાબતોનો નિર્ણય પરામર્શ દ્વારા કરો. 42:38
- તમારો અવાજ પયગંબરના અવાજથી ઊંચો ન કરો. 49:2
